package com.shoply.infrastructure.security;
import com.auth0.jwt.exceptions.JWTVerificationException; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.List; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter {private final JwtTokenService tokens;public JwtAuthenticationFilter(JwtTokenService tokens){this.tokens=tokens;}protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String header=req.getHeader("Authorization");if(header!=null&&header.startsWith("Bearer "))try{var jwt=tokens.verify(header.substring(7));var auth=new UsernamePasswordAuthenticationToken(jwt.getSubject(),null,List.of(new SimpleGrantedAuthority("ROLE_"+jwt.getClaim("role").asString())));SecurityContextHolder.getContext().setAuthentication(auth);}catch(JWTVerificationException ignored){SecurityContextHolder.clearContext();}chain.doFilter(req,res);}}
